-- mod-forever-racials: the new racial spells, their procs and scripts, and Cultivation's herbs.
-- The client gets the same spell rows from patch-P (tools/build_patch.py, which prints the
-- spell_dbc rows below with --sql).
--
--   90100 Big Game Hunter           Dwarf passive, a copy of Beast Slaying (20557): +5% damage to Beasts.
--   90101 Elune's Light             Night Elf active: +10% crit for 15 sec, 2 min cooldown.
--   90102 Escape Artist             the root and snare immunity Escape Artist now casts, 3 sec.
--   90103 Eureka!                   Gnome active: 3 charges, 20 sec: -25% cost, +10% damage and healing.
--   90104 Expansive Mind            Gnome, hidden: +5% max rage, energy and runic power.
--   90105 Shatter Curse             Orc active, Stoneform's twin: curse immunity, -10% magic damage taken, 8 sec.
--   90106 Touch of the Grave        Undead passive; its script rolls the chance and casts 90107.
--   90107 Touch of the Grave        the drain: a copy of an NPC's instant Shadow health leech (43125).
--   90108 Plainsrunning             Tauren passive; its script counts the seconds you keep moving.
--   90109 Plainsrunning             the speed buff, 1% per stack, 5 stacks.
--   90110 Cultivation               Tauren active; its script grows a herb (10 min cooldown).
--   90111 Rapid Regeneration        Troll active: 10% of max health every 2 sec for 10 sec, 3 min cooldown.
--
-- The spell ids must match src/ForeverRacials.cpp. Idempotent: safe to run again.

DELETE FROM `spell_dbc` WHERE `ID` IN (90100, 90101, 90102, 90103, 90104, 90105, 90106, 90107, 90108, 90109, 90110, 90111);

-- Touch of the Grave procs on damaging weapon attacks and harmful spells (not periodic damage);
-- the script rolls 5% or 10% and sets the cooldown from the config. Eureka! procs once when each
-- spell finishes (phase 4) and has 3 charges.
DELETE FROM `spell_proc` WHERE `SpellId` IN (90103, 90106);

DELETE FROM `spell_script_names` WHERE `ScriptName` IN ('spell_forever_blood_fury', 'spell_forever_touch_of_the_grave',
    'spell_forever_eureka', 'spell_forever_plainsrunning', 'spell_forever_cultivation');

-- Cultivation's herbs: copies of 40 herb nodes as 9500700-9500739, the same chests with the
-- same loot but no Herbalism lock (Data0 = 0), so anyone can gather them. Copied through a
-- temporary table so this works whatever columns the server's gameobject_template has. The
-- order must match HERBS in src/ForeverRacials.cpp:
-- Peacebloom, Silverleaf, Earthroot, Mageroyal, Briarthorn, Bruiseweed, Wild Steelbloom, Kingsblood, Grave Moss, Liferoot,
-- Fadeleaf, Goldthorn, Khadgar's Whisker, Wintersbite, Firebloom, Purple Lotus, Arthas' Tears, Sungrass, Blindweed, Ghost Mushroom,
-- Gromsblood, Golden Sansam, Dreamfoil, Mountain Silversage, Plaguebloom, Icecap, Felweed, Dreaming Glory, Ragveil, Terocone,
-- Flame Cap, Ancient Lichen, Netherbloom, Nightmare Vine, Goldclover, Tiger Lily, Talandra's Rose, Adder's Tongue, Lichbloom, Icethorn.
DROP TEMPORARY TABLE IF EXISTS `mod_forever_racials_herb`;
CREATE TEMPORARY TABLE `mod_forever_racials_herb` (`entry` INT UNSIGNED NOT NULL, `herb` INT UNSIGNED NOT NULL);

DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 9500700 AND 9500739;
DROP TEMPORARY TABLE IF EXISTS `mod_forever_racials_herb_template`;
CREATE TEMPORARY TABLE `mod_forever_racials_herb_template` AS
    SELECT `gameobject_template`.* FROM `gameobject_template`
    JOIN `mod_forever_racials_herb` ON `mod_forever_racials_herb`.`herb` = `gameobject_template`.`entry`;
UPDATE `mod_forever_racials_herb_template`
    JOIN `mod_forever_racials_herb` ON `mod_forever_racials_herb`.`herb` = `mod_forever_racials_herb_template`.`entry`
    SET `mod_forever_racials_herb_template`.`entry` = `mod_forever_racials_herb`.`entry`,
        `mod_forever_racials_herb_template`.`Data0` = 0,
        `mod_forever_racials_herb_template`.`ScriptName` = '';
DROP TEMPORARY TABLE `mod_forever_racials_herb_template`;
DROP TEMPORARY TABLE `mod_forever_racials_herb`;
